import { afterEach, beforeEach, describe, test, expect, vi } from 'vitest';
import { resolveBackgroundColour, resolveBorderColour, resolveTextColour, ZimmSizeChip } from './zimmSizeChip.css';

/**
 * The Figma state cascade (disabled > selected > default) is the part of this recipe that can
 * break without surfacing as a type or build error — a mis-ordered branch renders a
 * plausible-but-wrong colour. `index.test.tsx` mocks `useMultiStyleConfig` globally, so these
 * resolvers are never exercised by any shipped component test; these assertions are the only
 * thing that actually calls them. Mirrors zimmTextInput.css.test.ts's pattern for the same class
 * of untested-resolver gap.
 */

// .claude/rules/testing.md asks for beforeEach setup and vi.clearAllMocks() after each test.
// The resolvers here are pure and this file mocks nothing, so these hooks are a convention
// baseline rather than load-bearing isolation — kept so the file matches the rule as written
// and stays correct if a mock is ever introduced.

/**
 * Matches zimmSizeChip.css.ts's own (module-private, deliberately not re-exported)
 * ZimmSizeChipStyleProps shape structurally — TypeScript's structural typing means this file
 * doesn't need that type exported to pass a compatible object literal to the resolvers.
 */
type SizeChipStyleProps = {
  selected?: boolean;
  disabled?: boolean;
};

let base: SizeChipStyleProps;

beforeEach(() => {
  base = { selected: false, disabled: false };
});

afterEach(() => {
  vi.clearAllMocks();
});

describe('ZimmSizeChip — border colour precedence', () => {
  test('default: neither selected nor disabled uses the default field border', () => {
    expect(resolveBorderColour(base)).toBe('var(--zimm-color-border-forms)');
  });

  test('selected (not disabled) uses the focus border colour', () => {
    expect(resolveBorderColour({ ...base, selected: true })).toBe('var(--zimm-color-border-focus)');
  });

  test('disabled (not selected) uses the secondary border colour', () => {
    expect(resolveBorderColour({ ...base, disabled: true })).toBe('var(--zimm-color-border-secondary)');
  });

  test('disabled wins over selected', () => {
    expect(resolveBorderColour({ ...base, selected: true, disabled: true })).toBe(
      'var(--zimm-color-border-secondary)',
    );
  });
});

describe('ZimmSizeChip — background colour precedence', () => {
  test('default: neither selected nor disabled is transparent', () => {
    expect(resolveBackgroundColour(base)).toBe('transparent');
  });

  test('selected (not disabled) fills with the selected background colour', () => {
    expect(resolveBackgroundColour({ ...base, selected: true })).toBe('var(--zimm-color-bg-05)');
  });

  test('disabled (not selected) stays transparent', () => {
    expect(resolveBackgroundColour({ ...base, disabled: true })).toBe('transparent');
  });

  test('disabled wins over selected — stays transparent, not filled', () => {
    expect(resolveBackgroundColour({ ...base, selected: true, disabled: true })).toBe('transparent');
  });
});

describe('ZimmSizeChip — text colour precedence', () => {
  test('default: neither selected nor disabled uses the default text colour', () => {
    expect(resolveTextColour(base)).toBe('var(--zimm-color-text-default)');
  });

  test('selected (not disabled) uses the inverse text colour', () => {
    expect(resolveTextColour({ ...base, selected: true })).toBe('var(--zimm-color-text-inverse)');
  });

  test('disabled (not selected) uses the muted text colour', () => {
    expect(resolveTextColour({ ...base, disabled: true })).toBe('var(--zimm-color-text-muted)');
  });

  // This is the exact combination the Scorer proved regresses silently today: inverting the
  // disabled/selected precedence order in resolveTextColour let the whole 722-test suite stay
  // green. Disabled must win — a disabled chip should never read as selected/inverse-text.
  test('disabled wins over selected — muted, not inverse', () => {
    expect(resolveTextColour({ ...base, selected: true, disabled: true })).toBe('var(--zimm-color-text-muted)');
  });
});

describe('ZimmSizeChip — recipe wiring', () => {
  test('every declared part is produced by baseStyle', () => {
    const parts = Object.keys(ZimmSizeChip.baseStyle(base));
    expect(parts.sort()).toEqual([...ZimmSizeChip.parts].sort());
  });

  test('the chip colours reflect the resolved resolvers', () => {
    const props = { ...base, selected: true };
    const style = ZimmSizeChip.baseStyle(props);
    expect(style.chip.borderColor).toBe(resolveBorderColour(props));
    expect(style.chip.background).toBe(resolveBackgroundColour(props));
    expect(style.chip.color).toBe(resolveTextColour(props));
  });
});

